INSERT INTO [dbo].[PersonCategory]
([Name],[Description]) 
VALUES
(N'Category 1',N'Mobile individuals who perform life activities independently such as maintaining personal hygiene, bathing, dressing, handling physiological needs, eating independently, being conscious, oriented, and taking medical therapy independently (except insulin).'),
(N'Category 2', N'Semi-mobile individuals who need assistance with basic life activities such as bathing, dressing, eating, taking therapy, etc. Individuals who use diapers.'),
(N'Category 3', N'Immobile individuals who cannot perform life activities independently and require services such as bathing, maintaining personal hygiene, feeding, administering therapy, lifting and placing in a wheelchair, changing clothes, etc. Individuals who use diapers.'),
(N'Category 4', N'Individuals suffering from dementia, Alzheimer’s or non-Alzheimer’s, and mentally ill patients (including those with rare diseases).');
